// Explicit run-level route for retained S002 inputs. The initialization JSON
// remains unchanged and the historical bytes never receive a current-source,
// scene-fit, mission-admission, or readiness interpretation.
internal static class SourceS002HistoricalInputDiagnostic
{
    const string PhysicalSha = "8407889e4aff5c1f731c429fbae0063c5b6d99e1f7f51ab5c5c5bb0be29fa0b8";
    const string WaterSha = "acb0711c4e7046b70a696ee8fa935eef8a88c00d4dc23929ccb2b7812fcc15f5";
    const string StartupSha = "ceed295e16b473fbcba7444c6daa6347b5940c39dd6e80496321cb479c554c03";
    const string PreservationSha = "68b2a130fe08e3f952b1a8c1c0603b082ec38c7feb8b4581e1153cba7665e297";
