    internal static void RequireExistingPlacementDescriptorMatch(JObject originalOwnerDiagnostic, JObject historicalDescriptor)
    {
        if (originalOwnerDiagnostic == null || historicalDescriptor == null || originalOwnerDiagnostic.Count != 4 ||
            originalOwnerDiagnostic.Properties().Any(p => p.Name != "physical" && p.Name != "water" && p.Name != "startup" && p.Name != "relocation"))
            throw new InvalidDataException("Historical mode requires the exact immutable original-owner descriptor already bound by initialization");
        string[] oldNames = { "physical", "water", "startup", "relocation" };
        string[] newNames = { "physical", "water", "startup", "preservation" };
        for (int i = 0; i < oldNames.Length; i++)
        {
            var oldItem = originalOwnerDiagnostic[oldNames[i]] as JObject;
            var newItem = historicalDescriptor[newNames[i]] as JObject;
            if (oldItem == null || newItem == null || oldItem.Count != 2 || newItem.Count != 2 ||
                oldItem.Properties().Any(p => p.Name != "path" && p.Name != "sha256") ||
                newItem.Properties().Any(p => p.Name != "path" && p.Name != "sha256") ||
                (string)oldItem["path"] != (string)newItem["path"] ||
                (string)oldItem["sha256"] != (string)newItem["sha256"])
                throw new InvalidDataException("Historical input descriptor must exactly match the immutable initialization capture pins");
        }
    }
    static void RequireNoReparse(string path, string root)
    {
        var full = new FileInfo(path).FullName;
        var boundary = Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
        if (!full.StartsWith(boundary, StringComparison.Ordinal) || !File.Exists(full) || (File.GetAttributes(full) & FileAttributes.ReparsePoint) != 0)
            throw new InvalidDataException("Retained S002 input escaped root or is not a regular file");
        for (var parent = new FileInfo(full).Directory; parent != null && parent.FullName.Length >= boundary.Length - 1; parent = parent.Parent)
            if ((parent.Attributes & FileAttributes.ReparsePoint) != 0) throw new InvalidDataException("Symlink retained S002 input path forbidden");
    }

    internal static JObject Require(JObject run)
    {
        var descriptor = run["s002_historical_input_diagnostic"] as JObject;
        if (descriptor == null) return null;
        if ((string)run["mission"] != "S002" || descriptor.Count != 5 ||
            descriptor.Properties().Any(p => p.Name != "kind" && !Names.Contains(p.Name)) ||
            (string)descriptor["kind"] != "S002HistoricalInputOnlyDiagnostic")
            throw new NotSupportedException("Exact opt-in S002 historical-input diagnostic required");
        string repositoryValue = (string)run["repository_root"];
        string repositoryRoot = repositoryValue == null ? null : Path.GetFullPath(repositoryValue);
        string sourceValue = (string)run["source_repository_root"];
        string sourceRoot = sourceValue == null ? null : Path.GetFullPath(sourceValue);
        if (repositoryRoot == null || !Path.IsPathRooted(repositoryValue) || !Directory.Exists(repositoryRoot) || sourceRoot == null || !Path.IsPathRooted(sourceValue) || !Directory.Exists(sourceRoot))
            throw new InvalidDataException("Explicit repository root required for retained S002 inputs");
        string[] relative = {
            "Logs/SkirmishProduction/s073-source-inputs-20261101-r1/campaign-physical-source.json",
            "Logs/SkirmishProduction/s073-source-inputs-20261101-r1/campaign-water-capture.json",
            "Logs/SkirmishProduction/s073-source-inputs-20261101-r1/campaign-startup-observation.json",
            "Logs/SkirmishProduction/s073-captured-source-preservation-20261101-r1/receipt.json"
        };
        string[] hashes = { PhysicalSha, WaterSha, StartupSha, PreservationSha };
        for (int i = 0; i < Names.Length; i++)
        {
            var item = descriptor[Names[i]] as JObject;
            string expectedPath = Path.GetFullPath(Path.Combine(repositoryRoot, relative[i]));
            if (item == null || item.Count != 2 || item.Properties().Any(p => p.Name != "path" && p.Name != "sha256") ||
                (string)item["path"] != expectedPath || (string)item["sha256"] != hashes[i])
                throw new InvalidDataException("Retained S002 input descriptor differs: " + Names[i]);
            RequireNoReparse(expectedPath, repositoryRoot);
        }
        SourcePlacementDomain.LoadS002HistoricalInputOnly(
            (string)descriptor["physical"]["path"], PhysicalSha,
            (string)descriptor["water"]["path"], WaterSha,
            (string)descriptor["startup"]["path"], StartupSha,
            sourceRoot, (string)descriptor["preservation"]["path"], PreservationSha);
        return (JObject)descriptor.DeepClone();
    }

    internal static SourcePlacementDomain LoadDomain(JObject descriptor, string sourceRoot)
    {
        if (descriptor == null) return null;
        return SourcePlacementDomain.LoadS002HistoricalInputOnly(
            (string)descriptor["physical"]["path"], PhysicalSha,
            (string)descriptor["water"]["path"], WaterSha,
            (string)descriptor["startup"]["path"], StartupSha,
            sourceRoot, (string)descriptor["preservation"]["path"], PreservationSha);
    }

    internal static JObject Classification(bool sourceHostEntitiesMaterialized, int historicalNavigationRowsMaterialized) {
        if (historicalNavigationRowsMaterialized < 0 || historicalNavigationRowsMaterialized > 4954)
            throw new ArgumentOutOfRangeException(nameof(historicalNavigationRowsMaterialized));
        return new JObject {
        ["kind"] = "HistoricalInputOnlyDiagnostic_Unqualified",
        ["historical_input_epoch"] = "2026-11-01",
        ["physical_sha256"] = PhysicalSha,
        ["water_sha256"] = WaterSha,
        ["startup_sha256"] = StartupSha,
        ["preservation_sha256"] = PreservationSha,
        ["historical_producer_digest_bytes_verified"] = false,
        ["historical_producer_digest_only_count"] = 7,
        ["preserved_source_pin_count"] = 6526,
        ["preservation_project_file_count"] = 6522,
        ["preservation_external_pin_count"] = 4,
        ["historical_navigation_row_count"] = 4954,
        ["historical_navigation_rows_materialized"] = historicalNavigationRowsMaterialized,
        ["historical_navigation_rows_materialization_complete"] = historicalNavigationRowsMaterialized == 4954,
        ["source_host_entities_materialized"] = sourceHostEntitiesMaterialized,
        ["native_runtime_world_created"] = false,
        ["current_source_equivalence"] = false,
        ["current_blocker_equivalence"] = false,
        ["current_surface_equivalence"] = false,
        ["physical_source_fit"] = false,
        ["water_equivalence"] = false,
        ["scene_fit_certified"] = false,
        ["mission_admitted"] = false,
        ["mission_ready"] = false,
        ["native_world_created"] = false,
        ["native_scene_loaded"] = false,
        ["native_input_observed"] = false,
        ["player_order_observed"] = false,
        ["validated_victory"] = false
    };}
}
